export function renderBrandDeliveryEmail(vars: {
  brand_name: string;
  brand_slug: string;
  first_name: string;
  unsubscribe_url: string;
}): string {
  return TEMPLATE.replace(/\{\{\s*([a-z_]+)\s*\}\}/g, (_m, k: string) =>
    vars[k as keyof typeof vars] != null ? String(vars[k as keyof typeof vars]) : ""
  );
}

export function slugifyBrand(s: string): string {
  return s.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "") || "brand";
}
